import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static long pow(long a, long b) {
        long res = 1;
        long x = a % MOD;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = (res * x) % MOD;
            }
            x = (x * x) % MOD;
            b >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(pow(p, p - 1));
        } else if (k == 1) {
            System.out.println(pow(p, p));
        } else {
            long sz = 1;
            long pos = k % p;
            while (pos != 1) {
                sz++;
                pos = (pos * k) % p;
            }
            long cnt = (p - 1) / sz;
            System.out.println(pow(p, cnt));
        }
        sc.close();
    }
}
